{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "MicroPET imaging in mice showed that the close analogue GSK1838705A penetrated the BBB and produced moderate brain binding after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In an orthotopic glioma mouse model, ON013100 achieved a quasi-steady-state brain/plasma concentration ratio of 0.92, indicating high brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In mice, HI-236 reached brain concentrations comparable to plasma, demonstrating that this methoxy-substituted analogue readily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "SB-334867, a polar naphthyridine-containing analogue, showed CNS penetration with brain levels of 3.8 µM at 2 h after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Bosentan, which contains a tert-butylphenylsulfonamide and heteroaromatic core, produced detectable CSF levels after oral dosing in rabbits, supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Atenolol showed increased brain concentrations only after osmotic BBB disruption, indicating poor intrinsic CNS penetration; however, atenolol is markedly more hydrophilic than the query and is a weaker transfer anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple transferable in vivo measurements in close analogues demonstrate meaningful CNS access (brain/plasma ratios 0.38–0.92, PET brain binding, CSF detection), overriding the uncertain physicochemical prior. The main contradictory anchor, atenolol, is much more hydrophilic and less applicable to this lipophilic, mostly neutral query.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement is available for the query molecule itself.",
    "Unbound brain concentrations and the impact of efflux transporters are not experimentally defined for the query.",
    "Most supportive evidence reports total brain/plasma partitioning rather than pharmacologically active unbound brain exposure.",
    "High TPSA and molecular weight may still limit passive diffusion, but active uptake or reduced efflux could compensate."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

